import pathlib, sys

def replace(path, old, new, label):
    p = pathlib.Path(path)
    t = p.read_text()
    if old not in t:
        print(f"NOT FOUND: {label} in {path}")
        sys.exit(1)
    p.write_text(t.replace(old, new))
    print(f"OK: {label}")

